arguments.new_str:
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ── Build IChatClient via MEAI abstraction ─────────────────────────────
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// ── Register tools ─────────────────────────────────────────────────────
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchAsync,
        "web_search",
        "Search the web for information on a query. Returns a list of result titles, URLs, and snippets."),
    AIFunctionFactory.Create(notebook.AddNote,
        "add_note",
        "Save a research note with a title and body for later reference."),
    AIFunctionFactory.Create(notebook.GetNotes,
        "get_notes",
        "Retrieve all saved research notes."),
};

// ── Create the agent ───────────────────────────────────────────────────
const string instructions = """
    You are a research agent. Given a topic, you:
    1. Search the web for relevant information using the web_search tool.
    2. Save key findings as notes using the add_note tool.
    3. After gathering enough information, retrieve your notes with get_notes
       and produce a well-structured summary with source citations.
    Be thorough — perform multiple searches to cover different angles of the topic.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking tools",
    tools: tools);

// ── Run the agent ──────────────────────────────────────────────────────
