/// <summary>Searches the web using the Brave Search API or falls back to DuckDuckGo.</summary>
sealed class WebSearcher : IDisposable
{
    private readonly HttpClient _http = new() { Timeout = TimeSpan.FromSeconds(15) };
    private readonly string? _braveApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");

    public async Task<string> SearchAsync(
        [Description("The search query")] string query,
        [Description("Maximum number of results to return")] int maxResults = 5)
    {
        try
        {
            if (!string.IsNullOrEmpty(_braveApiKey))
            {
                return await BraveSearchAsync(query, maxResults);
            }

            return await DuckDuckGoSearchAsync(query, maxResults);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private async Task<string> BraveSearchAsync(string query, int maxResults)
    {
        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("X-Subscription-Token", _braveApiKey);
        request.Headers.Add("Accept", "application/json");

        using var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = new List<string>();

        if (doc.RootElement.TryGetProperty("web", out var web)
            && web.TryGetProperty("results", out var items))
        {
            foreach (var item in items.EnumerateArray().Take(maxResults))
            {
                var title = item.GetProperty("title").GetString();
                var link = item.GetProperty("url").GetString();
                var snippet = item.TryGetProperty("description", out var d) ? d.GetString() : "";
                results.Add($"- **{title}**\n  URL: {link}\n  {snippet}");
            }
        }

        return results.Count > 0
            ? string.Join("\n\n", results)
            : "No results found.";
    }

    private async Task<string> DuckDuckGoSearchAsync(string query, int maxResults)
    {
        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("User-Agent", "ResearchAgent/1.0");

        using var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync();

        // Parse result snippets from the HTML response
        var results = new List<string>();
        var snippetTag = "class=\"result__snippet\"";
        var titleTag = "class=\"result__a\"";
        var idx = 0;

        while (results.Count < maxResults)
        {
            var titleStart = html.IndexOf(titleTag, idx, StringComparison.Ordinal);
            if (titleStart < 0) break;

            var titleTextStart = html.IndexOf('>', titleStart + titleTag.Length);
            var titleTextEnd = html.IndexOf("</a>", titleTextStart, StringComparison.Ordinal);
            var title = titleTextStart >= 0 && titleTextEnd > titleTextStart
                ? StripHtml(html[(titleTextStart + 1)..titleTextEnd])
                : "Untitled";

            var hrefStart = html.LastIndexOf("href=\"", titleStart, Math.Min(titleStart, 200), StringComparison.Ordinal);
            var link = "";
            if (hrefStart >= 0)
            {
                var hrefEnd = html.IndexOf('"', hrefStart + 6);
                if (hrefEnd > hrefStart)
                    link = html[(hrefStart + 6)..hrefEnd];
            }

            var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
            var snippet = "";
            if (snippetStart >= 0)
            {
                var sTextStart = html.IndexOf('>', snippetStart + snippetTag.Length);
                var sTextEnd = html.IndexOf("</a>", sTextStart, StringComparison.Ordinal);
                if (sTextStart >= 0 && sTextEnd > sTextStart)
                    snippet = StripHtml(html[(sTextStart + 1)..sTextEnd]);
            }

            results.Add($"- **{title}**\n  URL: {link}\n  {snippet}");
            idx = (snippetStart > 0 ? snippetStart : titleStart) + 1;
        }

        return results.Count > 0
            ? string.Join("\n\n", results)
            : "No results found.";
    }

    private static string StripHtml(string html)
        => System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "").Trim();

